import type { MascotState } from "@hermit/runtime";
import type { RigPoseName } from "./mascot-rig.ts";

// Poses of the crab rig (scripts/brand/mascot.py), never redrawn (PDR-006). The app draws them as vectors from the
// rig's own traced pieces (mascot-rig.ts, generated by scripts/brand/mascot_app.py); docs/brand/mascot/png has the
// same poses as pictures, and the proof page (docs/design/mascot) shows the two match.
/** A pose of the rig: every chat state, plus the hello of the first run (HM-ONB-01, the empty chat). */
export type Pose = MascotState | "hello";

/** The rig pose each app pose shows, by its name in docs/brand/mascot/png. */
export const RIG_POSE: Record<Pose, RigPoseName> = {
  idle: "01-idle",
  thinking: "02-thinking",
  working: "03-working",
  asking: "04-asking",
  done: "05-done",
  error: "06-error",
  blocked: "07-blocked",
  offline: "08-offline",
  hello: "hello",
};

/** The copy key that says the same as the pose, so the mascot is never the only signal. */
export const mascotLabel: Record<MascotState, string> = {
  idle: "HM-CHAT-02.onPhone",
  thinking: "HM-CHAT-01.thinking",
  working: "HM-CHAT-01.working",
  asking: "HM-APPR-01.title",
  done: "HM-CHAT-02.onPhone",
  error: "common.outcome.model_error",
  blocked: "HM-APPR-01.denied",
  offline: "HM-CHAT-01.offline",
};
